def gate_dt(t, sch, inst, dt):
    nm = inst.operation.name
    if nm == "delay":
        return int(inst.operation.duration)
    if nm in ("barrier", "rz"):
        return 0
    qs = tuple(sch.find_bit(q).index for q in inst.qubits)
    return int(round(t[nm][qs].duration / dt))


def t_m(backend, isa, M):
    """M's timeline in the scheduled circuit (padded, so its instructions tile time): the end of its first sx and the
    start of its last sx, in dt."""
    t = backend.target
    sch = W.scheduled(isa, t)
    clock, sx = 0, []
    for inst in sch.data:
        qs = [sch.find_bit(q).index for q in inst.qubits]
        if M not in qs:
            continue
        d = gate_dt(t, sch, inst, backend.dt)
        if inst.operation.name == "sx" and len(qs) == 1:
            sx.append((clock, clock + d))
        clock += d
    return {"first_H_end_dt": sx[0][1], "last_H_start_dt": sx[-1][0], "T_M_dt": sx[-1][0] - sx[0][1],
            "T_M_us": (sx[-1][0] - sx[0][1]) * backend.dt * 1e6, "M_idle_windows_dt": W.idle_windows(sch, M), "M_total_dt": clock}


def x_on(c, q):
    return sum(1 for inst in c.data if inst.operation.name == "x" and c.find_bit(inst.qubits[0]).index == q)


def build(backend):
    t = backend.target
    gran = getattr(t, "granularity", 1) or 1
    ideal = W.wait_test_ideal()
    A, recA, tms = {}, {}, {}
    for name, chain in CHAINS.items():
        M = chain[1]
        no = W.build_wait_test(chain, False, backend)
        ref = W.build_wait_test(chain, True, backend)
        tms[name] = t_m(backend, no, M)
        for v, c in (("no", no), ("refocus", ref)):
            ops = {k: int(x) for k, x in c.count_ops().items()}
            init = list(c.layout.initial_index_layout(filter_ancillas=True))
            F = W.fidelity(W.exact_distribution(c), ideal)
            chk = {"cz_5": ops.get("cz", 0) == 5, "measures_6": ops.get("measure", 0) == 6, "resets_3": ops.get("reset", 0) == 3,
                   "no_swap": ops.get("swap", 0) == 0, "layout_as_named": init == chain, "exact_F_1": abs(F - 1) < 1e-6}
            if v == "refocus":
                chk["pulses_on_M"] = x_on(c, M) > x_on(no, M)
            A[(name, v)] = c
            recA[f"{name}|{v}"] = {"chain": chain, "M": M, "variant": v, "count_ops": ops, "exact_F": F, "checks": chk,
                                   "pulses_on_chain": {str(q): x_on(c, q) - x_on(no, q) for q in chain}}
    tm_values = sorted({W.even_wait(v["T_M_dt"], gran) for v in tms.values()})
    cover = {w: sum(1 for v in tms.values() if W.even_wait(v["T_M_dt"], gran) == w) for w in tm_values}
    tm_used = sorted(sorted(cover, key=lambda w: -cover[w])[:2])
    waits = list(W.KICKOFF_47_WAITS_DT) + tm_used + [W.even_wait(16e-6 / backend.dt, gran)]
    waits = sorted(set(waits))
    B, recB = [], []
    for e in W.part_b(GROUPS, waits, gran):
        isa = W.to_backend(e["circuit"], e["layout"], backend)
        lab = {**e["label"], "qubits": e["layout"]}
        p = W.exact_distribution(isa)
        worst = max(sum(v for k, v in p.items() if k[::-1][i] == "1") for i in range(len(e["layout"])))
        B.append((isa, lab))
        recB.append({"label": lab, "count_ops": {k: int(x) for k, x in isa.count_ops().items()}, "exact_max_P1": worst, "pass": worst < 1e-9})
    return A, recA, B, recB, tms, waits, tm_used, cover


def order(seed=SEED):
    rng = np.random.default_rng(seed)
    cells = [(n, v) for n in CHAINS for v in ("no", "refocus")]
    a_seq = [{"part": "W", "chain": CHAINS[cells[i][0]], "M": int(cells[i][0]), "variant": cells[i][1], "copy": c + 1}
             for c in range(COPIES) for i in rng.permutation(len(cells))]
    return a_seq, rng


def assemble(A, B, seed=SEED):
    a_seq, rng = order(seed)
    n_a, n_b = len(a_seq), len(B)
    slots = np.zeros(n_a + n_b, bool)
    slots[rng.choice(n_a + n_b, size=n_a, replace=False)] = True      # True: the next Part A circuit
    circs, labels, shots = [], [], []
    ia = ib = 0
    for s in slots:
        if s:
            lab = a_seq[ia]; ia += 1
            circs.append(A[(str(lab["M"]), lab["variant"])]); labels.append(lab); shots.append(SHOTS_A)
        else:
            c, lab = B[ib]; ib += 1
            circs.append(c); labels.append(lab); shots.append(SHOTS_B)
    return circs, labels, shots
